def encrypt(s):
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            new_ch = chr((ord(ch) - ord('a') + 4) % 26 + ord('a'))
            result.append(new_ch)
        elif 'A' <= ch <= 'Z':
            new_ch = chr((ord(ch) - ord('A') + 4) % 26 + ord('A'))
            result.append(new_ch)
        else:
            result.append(ch)
    return ''.join(result)
