def anti_shuffle(s):
    if not s:
        return s
    words = s.split(' ')
    result = []
    for word in words:
        if not word:
            result.append(word)
        else:
            # Sort characters by ASCII value
            sorted_chars = sorted(word, key=lambda c: ord(c))
            result.append(''.join(sorted_chars))
    return ' '.join(result)
